const planetDescriptions = {
  mercury:'Mercury is the smallest planet and the closest to the Sun. Its surface is covered in craters.',
  venus:'Venus has a thick carbon dioxide atmosphere and the hottest surface of any planet.',
  earth:'Earth is our home planet and the only world where life is currently confirmed.',
  mars:'Mars is known as the Red Planet. It has giant volcanoes, polar ice caps and two small moons.',
  jupiter:'Jupiter is the largest planet. It is a gas giant famous for its Great Red Spot.',
  saturn:'Saturn is a gas giant with spectacular rings made largely from ice and rocky fragments.',
  uranus:'Uranus is an ice giant that rotates almost on its side and has a blue-green appearance.',
  neptune:'Neptune is the most distant major planet, with extremely powerful winds in its atmosphere.'
};
const planetFacts = {
  mercury:['Smallest planet in the Solar System','Nearly airless and heavily cratered','Orbits the Sun in about 88 days'],
  venus:['Hottest planet despite being second from the Sun','Rotates in the opposite direction to most planets','Atmosphere is dominated by carbon dioxide'],
  earth:['Only known planet with life','Liquid water covers most of the surface','Has one natural moon'],
  mars:['Has the largest volcano in our Solar System','Known as the Red Planet','Has the moons Phobos and Deimos'],
  jupiter:['Largest planet in the Solar System','The Great Red Spot is a gigantic storm','Made mostly of hydrogen and helium'],
  saturn:['Known for its prominent icy rings','Less dense than liquid water on average','Has many moons'],
  uranus:['An ice giant with a sideways spin','Blue-green color comes from methane','Has faint rings'],
  neptune:['Farthest planet from the Sun','Very strong atmospheric winds','An ice giant with a deep blue appearance']
};

const planetValue = (body,prop) => body?.[prop] === undefined ? null : body[prop];
function setText(id,value) { SELECT(id).textContent = String(value); }
function updatePlanetDetail(id) {
  const key=id.toLowerCase(), reference=referencePlanets[key]; if(!reference)return;
  selectedPlanet=key;
  const body = planetLiveData.get(key) || reference;
  document.querySelectorAll('.planet-card').forEach(card=>card.setAttribute('aria-pressed',String(card.dataset.planetId===key)));
  setText('planet-detail-name',key[0].toUpperCase()+key.slice(1));
  setText('planet-detail-description',planetDescriptions[key]);
  SELECT('planet-detail-image').src=imageAsset(key+'.png');
  SELECT('planet-detail-image').alt=key+' illustration';
  setText('planet-distance',body.semimajorAxis != null ? `${pretty(body.semimajorAxis/1e6,1)}M km`:'N/A');
  setText('planet-radius',body.meanRadius != null ? `${pretty(body.meanRadius,1)} km`:'N/A');
  setText('planet-mass',body.mass ? `${pretty(body.mass.massValue,3)} × 10^${body.mass.massExponent} kg`:'N/A');
  setText('planet-density',body.density != null ? `${pretty(body.density,2)} g/cm³`:'N/A');
  setText('planet-orbital-period',body.sideralOrbit != null ? (Math.abs(body.sideralOrbit)>730 ? `${pretty(body.sideralOrbit/365.25,2)} years` : `${pretty(body.sideralOrbit,1)} days`) : 'N/A');
  setText('planet-rotation',body.sideralRotation != null ? `${pretty(Math.abs(body.sideralRotation),2)} hours${body.sideralRotation < 0?' (retrograde)':''}` : 'N/A');
  setText('planet-moons',Array.isArray(body.moons) ? body.moons.length : 'Data unavailable');
  setText('planet-gravity',body.gravity != null ? `${pretty(body.gravity,2)} m/s²` : 'N/A');
  setText('planet-discoverer',body.discoveredBy || 'Known since antiquity');
  setText('planet-discovery-date',body.discoveryDate || 'Ancient');
  setText('planet-body-type',body.bodyType || 'Planet');
  setText('planet-volume',body.vol ? `${pretty(body.vol.volValue,3)} × 10^${body.vol.volExponent} km³`:'N/A');
  setText('planet-perihelion',body.perihelion != null ? `${pretty(body.perihelion/1e6,1)}M km` : 'N/A');
  setText('planet-aphelion',body.aphelion != null ? `${pretty(body.aphelion/1e6,1)}M km` : 'N/A');
  setText('planet-eccentricity',body.eccentricity != null ? pretty(body.eccentricity,4) : 'N/A');
  setText('planet-inclination',body.inclination != null ? `${pretty(body.inclination,2)}°` : 'N/A');
  setText('planet-axial-tilt',body.axialTilt != null ? `${pretty(body.axialTilt,2)}°` : 'N/A');
  setText('planet-temp',body.avgTemp != null ? `${pretty(body.avgTemp-273.15,1)}°C` : 'N/A');
  setText('planet-escape',body.escape != null ? `${pretty(body.escape/1000,2)} km/s` : 'N/A');
  SELECT('planet-facts').innerHTML=planetFacts[key].map(text=>`<li class="flex items-start"><span class="text-green-400 mr-2">✓</span><span class="text-slate-300">${escapeHTML(text)}</span></li>`).join('');
}

function updateComparison() {
  const t=SELECT('planet-comparison-tbody'); if(!t) return;
  t.innerHTML=PLANET_NAMES.map(id=>{
    const p=planetLiveData.get(id)||referencePlanets[id];
    const period = p.sideralOrbit != null ? (p.sideralOrbit >= 730 ? `${pretty(p.sideralOrbit/365.25,1)} years` : `${pretty(p.sideralOrbit,0)} days`):'N/A';
    const kind=['jupiter','saturn'].includes(id) ? 'Gas Giant':(['uranus','neptune'].includes(id)?'Ice Giant':'Terrestrial');
    const massEarth = p.mass ? (Number(p.mass.massValue) * 10 ** Number(p.mass.massExponent)) / 5.972e24 : null;
    const className = {mercury:'bg-yellow-500',venus:'bg-yellow-500',earth:'bg-blue-500',mars:'bg-red-400',jupiter:'bg-yellow-400',saturn:'bg-yellow-400',uranus:'bg-blue-400',neptune:'bg-blue-500'}[id];
    return `<tr class="hover:bg-slate-800/30"><td class="px-4 md:px-6 py-3 md:py-4 sticky left-0 bg-slate-800 z-10"><div class="flex gap-2 items-center"><span class="w-6 h-6 rounded-full ${className}"></span><strong>${id[0].toUpperCase()+id.slice(1)}</strong></div></td>
      <td class="px-4 md:px-6 py-3 md:py-4">${pretty(p.semimajorAxis/149597870.7,2)}</td>
      <td class="px-4 md:px-6 py-3 md:py-4">${pretty(p.meanRadius*2,0)}</td>
      <td class="px-4 md:px-6 py-3 md:py-4">${massEarth == null ? 'N/A' : pretty(massEarth,2)}</td>
      <td class="px-4 md:px-6 py-3 md:py-4">${escapeHTML(period)}</td>
      <td class="px-4 md:px-6 py-3 md:py-4">${Array.isArray(p.moons)?p.moons.length:'N/A'}</td>
      <td class="px-4 md:px-6 py-3 md:py-4"><span class="status-pill">${kind}</span></td></tr>`;
  }).join('');
}

function initialize() {
  document.querySelectorAll('.nav-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showSection(link.dataset.section);}));
  SELECT('sidebar-toggle').addEventListener('click',()=>SELECT('sidebar').classList.toggle('sidebar-open'));
  const dateInput = SELECT('apod-date-input');
  dateInput.max=todayLocal();
  dateInput.value=todayLocal();
  const label=dateInput.parentElement.querySelector('span');
  if(label) {label.textContent=formatDate(todayLocal()+'T12:00:00Z');dateInput.addEventListener('change',()=>label.textContent=dateInput.value?formatDate(dateInput.value+'T12:00:00Z'):'Choose date');}
  SELECT('load-date-btn').addEventListener('click',()=>{
    const value=dateInput.value;
    if(!value || value>todayLocal() || value<'1995-06-16')return notice('apod-status','Choose a date between June 16, 1995 and today.',true);
    loadApod(value);
  });
  SELECT('today-apod-btn').addEventListener('click',()=>{dateInput.value=todayLocal();if(label)label.textContent=formatDate(todayLocal()+'T12:00:00Z');loadApod(todayLocal());});
  SELECT('launches').addEventListener('click',e=>{
    const target=e.target.closest('[data-details],[data-favorite],[data-calendar]');if(!target)return;
    if(target.dataset.details!=null)viewLaunch(Number(target.dataset.details));
    else if(target.dataset.favorite!=null)toggleFavorite(Number(target.dataset.favorite));
    else if(target.dataset.calendar!=null)downloadReminder(Number(target.dataset.calendar));
  });
  SELECT('close-launch-dialog').addEventListener('click',()=>SELECT('launch-dialog').close());
  SELECT('launch-dialog').addEventListener('click',e=>{if(e.target===SELECT('launch-dialog'))SELECT('launch-dialog').close();});
  document.querySelectorAll('.planet-card').forEach(card=>{
    card.setAttribute('role','button');card.setAttribute('tabindex','0');
    card.addEventListener('click',()=>updatePlanetDetail(card.dataset.planetId));
    card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();updatePlanetDetail(card.dataset.planetId);}});
  });
  const learn=SELECT('planets').querySelector('button.w-full.py-3');
  if(learn)learn.addEventListener('click',()=>window.open('https://science.nasa.gov/solar-system/planets/', '_blank','noopener,noreferrer'));
  updatePlanetDetail('earth');updateComparison();
  showSection('today-in-space');
  loadApod(todayLocal());
}

document.addEventListener('DOMContentLoaded',()=>{
  document.querySelectorAll('img[data-image-file]').forEach(img => { img.src = imageAsset(img.dataset.imageFile); });
  initialize();
});
